import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class JDOMNodePointer_testNode_TriageGen0Test {

    // Mock classes to satisfy the interface/types if not easily instantiable
    private interface NodeNameTest extends NodeTest {
        QName getNodeName();
        String getNamespaceURI();
        boolean isWildcard();
    }

    private interface NodeTypeTest extends NodeTest {
        int getNodeType();
    }

    private interface ProcessingInstructionTest extends NodeTest {
        String getTarget();
    }

    @Test
    public void testNullTestReturnsTrue() {
        NodePointer pointer = mock(NodePointer.class);
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, new Object(), null));
    }

    @Test
    public void testNodeNameTest_NotElementReturnsFalse() {
        NodePointer pointer = mock(NodePointer.class);
        NodeNameTest test = mock(NodeNameTest.class);
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, "NotAnElement", test));
    }

    @Test
    public void testNodeNameTest_WildcardWithNoPrefixReturnsTrue() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("foo");
        NodeNameTest test = mock(NodeNameTest.class);

        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName(null, null, null)); // prefix is null

        Assert.assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_WildcardMatches() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("foo");
        NodeNameTest test = mock(NodeNameTest.class);

        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName("any", "name", "uri"));

        Assert.assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_LocalNameMatch_NamespaceMatch() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("foo", new org.jdom2.Namespace("p", "uri"));
        NodeNameTest test = mock(NodeNameTest.class);

        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("name", "p", "uri"));
        when(test.getNamespaceURI()).thenReturn("uri");

        Assert.assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_LocalNameMatch_PrefixMatchWhenNSNull() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("foo", new org.jdom2.Namespace("p", null));
        NodeNameTest test = mock(NodeNameTest.class);

        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("foo", "p", null));
        when(test.getNamespaceURI()).thenReturn(null);

        // equalStrings(null, null) should be true based on logic flow
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeNameTest_LocalNameMismatchReturnsFalse() {
        NodePointer pointer = mock(NodePointer.class);
        Element element = new Element("foo");
        NodeNameTest test = mock(NodeNameTest.class);

        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("bar"));

        Assert.assertFalse(JDOMNodePointer.testNode(pointer, element, test));
    }

    @Test
    public void testNodeTypeTest_NodeTypes() {
        NodePointer pointer = mock(NodePointer.class);

        // NODE_TYPE_NODE
        NodeTypeTest nodeTest = mock(NodeTypeTest.class);
        when(nodeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, new Element("e"), nodeTest));
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, new Document(), nodeTest));
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Text("t"), nodeTest));

        // NODE_TYPE_TEXT
        NodeTypeTest textTest = mock(NodeTypeTest.class);
        when(textTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_TEXT);
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, new Text("t"), textTest));
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, mock(CDATA.class), textTest));
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), textTest));

        // NODE_TYPE_COMMENT
        NodeTypeTest commentTest = mock(NodeTypeTest.class);
        when(commentTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_COMMENT);
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, new Comment("c"), commentTest));
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), commentTest));

        // NODE_TYPE_PI
        NodeTypeTest piTest = mock(NodeTypeTest.class);
        when(piTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_PI);
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, new ProcessingInstruction("target", "val"), piTest));
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), piTest));

        // Unknown Type
        NodeTypeTest unknownTest = mock(NodeTypeTest.class);
        when(unknownTest.getNodeType()).thenReturn(999);
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), unknownTest));
    }

    @Test
    public void testProcessingInstructionTest_Match() {
        NodePointer pointer = mock(NodePointer.class);
        ProcessingInstruction pi = new ProcessingInstruction("target", "content");
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);

        when(test.getTarget()).thenReturn("target");
        Assert.assertTrue(JDOMNodePointer.testNode(pointer, pi, test));

        when(test.getTarget()).thenReturn("wrong");
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, pi, test));
    }

    @Test
    public void testProcessingInstructionTest_NotPIReturnsFalse() {
        NodePointer pointer = mock(NodePointer.class);
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), test));
    }

    @Test
    public void testUnknownTestTypeReturnsFalse() {
        NodePointer pointer = mock(NodePointer.class);
        NodeTest test = mock(NodeTest.class); // Not one of the specific types
        Assert.assertFalse(JDOMNodePointer.testNode(pointer, new Element("e"), test));
    }

    // Helper to simulate equalStrings which is used in the method
    private boolean equalStrings(String s1, String s2) {
        if (s1 == null && s2 == null) return true;
        if (s1 == null || s2 == null) return false;
        return s1.equals(s2);
    }
}
